import { href, navigate } from '../app/router';
import { useLang, useSetting, useT } from '../app/settings';
import { useStore } from '../app/store';
import { Showcase, type ShowcaseState } from '../app/showcase';
import { Store } from '../app/store';
import { fetchScene } from '../app/session';
import { formatSpan } from '../app/units';
import { tx, SIMULATION_LABEL, type Lang, type SceneFile } from '../content/catalog';
import { CATALOG_INDEX } from '../content/catalog.generated';
import { FEATURE_STATUS, HANDBOOK_PARTS, CHAPTERS, type FeatureKey } from '../content/handbook';
