import { OrbitSchematic } from './OrbitSchematic';

// Showcase worlds: each is framed as a close-up of one body, with its system behind it. Camera framing only: the
// engine runs the real catalogue world at the given rate (simulated seconds per second).
const SHOWCASE: { id: string; focus: string; framing: Framing; rate: number }[] = [
  { id: 'real.solar_system', focus: 'saturn', framing: { phaseDeg: 34, elevationDeg: 21, distance: 7.6 }, rate: 3600 },
  { id: 'real.trappist_1', focus: 'trappist_1_e', framing: { phaseDeg: 52, elevationDeg: 9, distance: 3.6 }, rate: 1800 },
  { id: 'real.kepler_16', focus: 'kepler_16_b', framing: { phaseDeg: 48, elevationDeg: 11, distance: 3.8 }, rate: 7200 },
  { id: 'real.sgr_a_s2', focus: 'sgr_a_star', framing: { phaseDeg: 30, elevationDeg: 13, distance: 2.4 }, rate: 3 * 86400 },
];
const FEATURED = ['real.solar_system', 'real.trappist_1', 'real.kepler_16', 'real.sgr_a_s2'];

const CAPABILITIES: { icon: IconName; title: 'home.f.physics.t' | 'home.f.edit.t' | 'home.f.create.t' | 'home.f.time.t' | 'home.f.save.t' | 'home.f.learn.t'; body: 'home.f.physics.b' | 'home.f.edit.b' | 'home.f.create.b' | 'home.f.time.b' | 'home.f.save.b' | 'home.f.learn.b'; feature: FeatureKey }[] = [
  { icon: 'orbit', title: 'home.f.physics.t', body: 'home.f.physics.b', feature: 'dynamics_engine' },
  { icon: 'target', title: 'home.f.edit.t', body: 'home.f.edit.b', feature: 'edit_body' },
  { icon: 'plus', title: 'home.f.create.t', body: 'home.f.create.b', feature: 'add_body' },
  { icon: 'clock', title: 'home.f.time.t', body: 'home.f.time.b', feature: 'time_controls' },
  { icon: 'save', title: 'home.f.save.t', body: 'home.f.save.b', feature: 'save_local' },
  { icon: 'book', title: 'home.f.learn.t', body: 'home.f.learn.b', feature: 'lessons' },
];

function StatusChip({ feature, lang }: { feature: FeatureKey; lang: Lang }) {
  const t = useT();
  const st = FEATURE_STATUS[feature]?.status ?? 'planned';
  const label = st === 'available' ? t('status.available') : st === 'partial' ? t('handbook.status.partial') : t('status.planned');
  return (
    <span className={`chip chip-${st}`} title={tx(FEATURE_STATUS[feature]?.note, lang) || undefined}>
      {label}
    </span>
  );
}

/** Horizontal shift of the hero picture: none on narrow screens, more where the headline takes a larger share. */
function heroOffset(width: number): number {
  if (width < 900) return 0;
  if (width < 1250) return 0.27;
  if (width < 1500) return 0.23;
  return 0.2;
}

function useHeroOffset(): number {
  const [off, setOff] = useState(() => heroOffset(window.innerWidth));
  useEffect(() => {
    const on = () => setOff(heroOffset(window.innerWidth));
    window.addEventListener('resize', on);
    return () => window.removeEventListener('resize', on);
  }, []);
  return off;
}

const IDLE_STORE = new Store<ShowcaseState>({ status: 'loading', sceneId: '', scene: null, simTime: 0, error: null, cameraSerial: 0 });

function Hero() {
  const t = useT();
  const lang = useLang();
  const reduced = useSetting('reducedMotion');
  const offset = useHeroOffset();
  // One showcase engine per effect lifecycle (StrictMode-safe): created here, disposed by this effect's cleanup.
  const [showcase, setShowcase] = useState<Showcase | null>(null);
  useEffect(() => {
    const sc = new Showcase(!reduced);
    setShowcase(sc);
    return () => {
      sc.dispose();
      setShowcase((cur) => (cur === sc ? null : cur));
    };
  }, [reduced]);
  const [index, setIndex] = useState(0);
  const item = SHOWCASE[index] ?? SHOWCASE[0]!;
  useEffect(() => {
    if (showcase) void showcase.show(item.id, item.rate);
  }, [showcase, item]);
  const state = useStore(showcase?.store ?? IDLE_STORE, (s) => s);

  const camera: CameraRequest | undefined = state.scene
    ? { serial: state.cameraSerial, id: null, key: item.focus, fit: false, framing: item.framing, animate: false }
    : undefined;
  const sceneName = tx(state.scene?.name, lang);
  const overrides = useMemo(() => ({ showLabels: false, showTracers: true, viewOffsetX: offset, hideFocusPath: true }), [offset]);
  const sceneId = item.id;

  return (
    <section className="hero" aria-labelledby="hero-title">
      {showcase && <Viewport source={showcase} interactive={false} autoRotate={!reduced} camera={camera} className="hero-view" overrides={overrides} />}
      <div className="hero-shade" aria-hidden="true" />
      <div className="hero-content">
        <p className="eyebrow">{t('home.eyebrow')}</p>
        <h1 id="hero-title">{t('home.title')}</h1>
        <p className="hero-lead">{t('home.lead')}</p>
        <div className="hero-ctas">
          <a className="btn btn-primary btn-lg" href={href('/universe')}>
            <Icon name="galaxy" />
            {t('home.ctaUniverse')}
          </a>
          <a className="btn btn-lg" href={href('/sandbox')}>
            <Icon name="sandbox" />
            {t('home.ctaSandbox')}
          </a>
          <a className="btn btn-lilac btn-lg" href={href('/handbook')}>
            <Icon name="book" />
            {t('home.ctaHandbook')}
          </a>
        </div>
        <a className="hero-more" href={href('/library')}>
          {t('home.ctaLibrary')}
          <Icon name="chevronRight" size={16} />
        </a>
      </div>
      <div className="hero-caption">
        <div className="hero-live">
          <span className={'live-dot ' + state.status} aria-hidden="true" />
          <span className="hero-live-label">{state.status === 'live' ? t('home.live') : state.status === 'loading' ? t('engine.loading') : t('home.preview')}</span>
          <span className="hero-live-text">
            {state.status === 'live'
              ? t('home.liveCaption', { scene: sceneName, elapsed: formatSpan(state.simTime, lang, 3) })
              : sceneName
                ? t('home.previewCaption', { scene: sceneName })
                : t('common.loading')}
          </span>
        </div>
        <div className="hero-worlds" role="group" aria-label={t('home.featured')}>
          {SHOWCASE.map((w, i) => {
            const entry = CATALOG_INDEX.scenes.find((s) => s.id === w.id);
            return (
              <button key={w.id} type="button" className={'world-chip' + (w.id === sceneId ? ' active' : '')} aria-pressed={w.id === sceneId} onClick={() => setIndex(i)}>
                {tx(entry?.name, lang) || w.id}
              </button>
            );
          })}
        </div>
      </div>
    </section>
  );
}

function FeaturedCard({ id }: { id: string }) {
  const t = useT();
  const lang = useLang();
  const entry = CATALOG_INDEX.scenes.find((s) => s.id === id);
  const [doc, setDoc] = useState<SceneFile | null>(null);
  useEffect(() => {
    let live = true;
    fetchScene(id)
      .then((d) => live && setDoc(d))
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, [id]);
  if (!entry) return null;
  return (
    <article className="world-card">
      <div className="world-card-art">{doc ? <OrbitSchematic scene={doc} /> : <span className="spinner" />}</div>
      <div className="world-card-body">
        <p className="world-card-kind">
          {tx(entry.kindLabel, lang)} · {tx(entry.groupLabel, lang)}
        </p>
        <h3>{tx(entry.name, lang)}</h3>
        <p className="muted">{tx(entry.description, lang)}</p>
        <p className="world-card-meta faint">
          {t('library.bodies', { n: entry.bodyCount })} · {tx(SIMULATION_LABEL, lang)}
        </p>
      </div>
      <button type="button" className="btn btn-ghost world-card-cta" onClick={() => navigate(`/sandbox?scene=${encodeURIComponent(id)}`)}>
        {t('home.openWorld')}
        <Icon name="chevronRight" size={17} />
      </button>
    </article>
  );
}

