// AiXenix Cosmos Lab web client: a schematic top view of a scene (logarithmic distances, not to scale), drawn from the
// scene file's initial positions. Labelled as a schematic wherever it is used.

import { useMemo } from 'react';
import type { SceneFile } from '../content/catalog';
import { blackbodyColor } from '../app/astro';

function colorOf(b: SceneFile['bodies'][number]): string {
  const p = (b.appearance?.params ?? {}) as Record<string, unknown>;
  const pick = (k: string) => (Array.isArray(p[k]) ? (p[k] as number[]) : null);
  let c = pick('StarColor') ?? pick('ColorA') ?? pick('LandColorA') ?? null;
  if (!c && b.class === 'star') {
    const teff = (b.star as { teff_k?: number } | undefined)?.teff_k ?? 5800;
    c = blackbodyColor(teff);
  }
  if (!c) c = b.class === 'black_hole' ? [1, 0.7, 0.4] : [0.7, 0.75, 0.85];
  const m = Math.max(c[0]!, c[1]!, c[2]!, 0.05);
  const k = Math.min(1 / m, 2.5);
  const to = (x: number) => Math.round(Math.min(255, (x * k * 0.85 + 0.12) * 255));
  return `rgb(${to(c[0]!)}, ${to(c[1]!)}, ${to(c[2]!)})`;
}

export function OrbitSchematic({ scene, size = 220 }: { scene: SceneFile; size?: number }) {
  const shapes = useMemo(() => {
    const bodies = scene.bodies;
    let m = 0;
    const com = [0, 0, 0];
    for (const b of bodies) {
      m += b.mass_kg;
      for (let i = 0; i < 3; i++) com[i]! += b.position_m[i]! * b.mass_kg;
    }
    if (m > 0) for (let i = 0; i < 3; i++) com[i]! /= m;
    const pts = bodies.map((b) => {
      const dx = b.position_m[0] - com[0]!;
      const dy = b.position_m[1] - com[1]!;
      return { b, d: Math.hypot(dx, dy), a: Math.atan2(dy, dx) };
    });
    const ds = pts.map((p) => p.d).filter((d) => d > 0);
    const dmin = ds.length ? Math.min(...ds) : 1;
    const dmax = ds.length ? Math.max(...ds) : 1;
    const d0 = dmin * 0.6;
    const R = size / 2 - 14;
    const r = (d: number) => (d <= 0 ? 0 : 18 + ((R - 18) * Math.log(1 + d / d0)) / Math.log(1 + dmax / d0));
    const maxMass = Math.max(...bodies.map((b) => b.mass_kg));
    return pts.map((p) => {
      const rr = r(p.d);
      const isStar = p.b.class === 'star' || p.b.class === 'black_hole' || p.b.class === 'white_dwarf' || p.b.class === 'pulsar';
      const dot = isStar ? 6 + 3 * Math.cbrt(p.b.mass_kg / maxMass) : 2.2 + 2.6 * Math.cbrt(p.b.mass_kg / maxMass);
      return { id: p.b.id, rr, x: size / 2 + rr * Math.cos(p.a), y: size / 2 - rr * Math.sin(p.a), dot, color: colorOf(p.b), star: isStar };
    });
  }, [scene, size]);

  return (
    <svg className="orbit-schematic" viewBox={`0 0 ${size} ${size}`} width={size} height={size} role="img" aria-label={`${scene.id} schematic`}>
      <defs>
        <radialGradient id={`glow-${scene.id}`}>
          <stop offset="0" stopColor="rgba(255,240,220,0.55)" />
          <stop offset="1" stopColor="rgba(255,240,220,0)" />
        </radialGradient>
      </defs>
      {shapes.map((s) =>
        s.rr > 0 ? <circle key={'o' + s.id} cx={size / 2} cy={size / 2} r={s.rr} fill="none" stroke="rgba(140,190,255,0.22)" strokeWidth={0.8} /> : null,
      )}
      {shapes
        .filter((s) => s.star)
        .map((s) => (
          <circle key={'g' + s.id} cx={s.x} cy={s.y} r={s.dot * 3.2} fill={`url(#glow-${scene.id})`} />
        ))}
      {shapes.map((s) => (
        <circle key={'b' + s.id} cx={s.x} cy={s.y} r={s.dot} fill={s.color} />
      ))}
    </svg>
  );
}
