// AiXenix Cosmos Lab web client: the landing page's live showcase. It runs its own engine instance (independent of the
// sandbox world) and is disposed when the page closes. Without the engine it shows the catalogue initial state, labelled.

import type { EngineController, EngineSnapshot } from '../engine/types';
import type { SceneFile } from '../content/catalog';
import type { ViewFrame } from '../render/SpaceView';
import type { FrameSource } from '../ui/Viewport';
import { appearanceFromScene, createEngineInstance, errorText, fetchScene, previewFromScene } from './session';
import { Store } from './store';

export interface ShowcaseState {
  status: 'loading' | 'live' | 'preview' | 'error';
  sceneId: string;
  scene: SceneFile | null;
  simTime: number;
  error: string | null;
  cameraSerial: number;
}

export class Showcase implements FrameSource {
  readonly store = new Store<ShowcaseState>({ status: 'loading', sceneId: '', scene: null, simTime: 0, error: null, cameraSerial: 0 });
  private engine: EngineController | null = null;
  private enginePromise: Promise<EngineController | null> | null = null;
  private frame: ViewFrame | null = null;
  private readonly listeners = new Set<() => void>();
  private token = 0;
  private disposed = false;
  private lastCaption = 0;
  private unsubscribe: (() => void) | null = null;

  constructor(private readonly play: boolean) {}

  get = (): ViewFrame | null => this.frame;

  subscribe = (l: () => void): (() => void) => {
    this.listeners.add(l);
    return () => this.listeners.delete(l);
  };

  private emit(): void {
    for (const l of [...this.listeners]) l();
  }

  private getEngine(): Promise<EngineController | null> {
    if (this.engine) return Promise.resolve(this.engine);
    if (!this.enginePromise) {
      this.enginePromise = (async () => {
        try {
          const e = await createEngineInstance();
          await e.ready;
          if (this.disposed) {
            e.dispose();
            return null;
          }
          this.engine = e;
          this.unsubscribe = e.subscribe((snap) => this.onSnapshot(snap));
          return e;
        } catch (err) {
          this.store.set({ error: errorText(err) });
          return null;
        }
      })();
    }
    return this.enginePromise;
  }

  private sceneDoc: SceneFile | null = null;

  private onSnapshot(snap: EngineSnapshot): void {
    if (this.disposed || !this.sceneDoc || snap.sceneId !== this.sceneDoc.id) return;
    const cur = this.frame?.snapshot;
    if (cur && cur.worldId === snap.worldId && snap.sequence <= cur.sequence) return;
    this.frame = { snapshot: snap, appearance: this.appearance, tracerLooks: {}, selectedId: null, sky: this.sky };
    this.emit();
    const now = performance.now();
    if (now - this.lastCaption > 500) {
      this.lastCaption = now;
      this.store.set({ simTime: snap.simTime });
    }
  }

  private appearance: ViewFrame['appearance'] = {};
  private sky = 'Sky_MilkyWay';

  /** Loads a catalogue scene into the showcase engine and plays it at `rate` simulated seconds per second. */
  async show(sceneId: string, rate?: number): Promise<void> {
    const token = ++this.token;
    this.store.set({ status: 'loading', sceneId, error: null });
    let doc: SceneFile;
    try {
      doc = await fetchScene(sceneId);
    } catch (e) {
      if (token === this.token) this.store.set({ status: 'error', error: errorText(e) });
      return;
    }
    if (token !== this.token || this.disposed) return;
    this.sceneDoc = doc;
    this.appearance = appearanceFromScene(doc);
    this.sky = (doc as unknown as { sky_profile?: string }).sky_profile ?? 'Sky_MilkyWay';
    // Show the initial state at once; the engine replaces it as soon as it runs.
    this.frame = { snapshot: previewFromScene(doc), appearance: this.appearance, tracerLooks: {}, selectedId: null, sky: this.sky };
    this.emit();
    this.store.set({ scene: doc, simTime: 0, cameraSerial: this.store.get().cameraSerial + 1 });
    const eng = await this.getEngine();
    if (token !== this.token || this.disposed) return;
    if (!eng) {
      this.store.set({ status: 'preview' });
      return;
    }
    try {
      await eng.stop().catch(() => undefined);
      const res = await eng.loadScene(doc, { startPaused: true });
      if (token !== this.token || this.disposed) return;
      this.frame = { snapshot: res.snapshot, appearance: this.appearance, tracerLooks: {}, selectedId: null, sky: this.sky };
      this.emit();
      if (this.play) {
        await eng.resume();
        const hint = res.timeScaleHint > 0 ? res.timeScaleHint : doc.physics?.time_scale_hint ?? 86400;
        await eng.play(rate ?? hint);
      }
      if (token === this.token) this.store.set({ status: this.play ? 'live' : 'preview' });
    } catch (e) {
      if (token === this.token) this.store.set({ status: 'preview', error: errorText(e) });
    }
  }

  dispose(): void {
    this.disposed = true;
    this.unsubscribe?.();
    this.engine?.dispose();
    this.engine = null;
    this.listeners.clear();
  }
}
